int total_nodes;
infile.read(reinterpret_cast<char *>(&total_nodes), sizeof(total_nodes));

for (int i = 0; i < total_nodes; i++) {
    unsigned char indicator;
    infile.read(reinterpret_cast<char *>(&indicator), sizeof(indicator));

    if (indicator == 1) {
        unsigned char character;
        infile.read(reinterpret_cast<char *>(&character), sizeof(character));

        while (current->left != nullptr && current->right != nullptr) {
            current = current->parent;
        }

        if (current->left == nullptr) {
            current->left = std::make_shared<Node>(character, 0);
            current->left->parent = current;
            current = current->left;
        } else if (current->right == nullptr) {
            current->right = std::make_shared<Node>(character, 0);
            current->right->parent = current;
            current = current->right;
        }
    } else {
        unsigned char character;
        infile.read(reinterpret_cast<char *>(&character), sizeof(character));

        std::shared_ptr<Node> new_node = std::make_shared<Node>(character, 0);
        new_node->parent = current;

        if (current->left == nullptr) {
            current->left = new_node;
        } else {
            current->right = new_node;
        }

        while (current->parent != nullptr && current->parent->right == current) {
            current = current->parent;
        }

        if (current->parent != nullptr) {
            current = current->parent;
        } else {
            current = root;
        }
    }
}

